pub(super) fn accepted(element: &str, charge: i32, valence: usize) -> bool {
    let element = if matches!(element, "D" | "T") {
        "H"
    } else {
        element
    };
    let Some(index) = charge.checked_add(3).and_then(|q| usize::try_from(q).ok()) else {
        return false;
    };
    let Some((_, masks)) = MASKS.iter().find(|(symbol, _)| *symbol == element) else {
        return false;
    };
    masks
        .get(index)
        .is_some_and(|mask| valence < 10 && mask & (1 << valence) != 0)
}

pub(super) fn neutral_degree(element: &str) -> Option<usize> {
    match element {
        "C" => Some(4),
        "N" | "B" => Some(3),
        "O" => Some(2),
        "F" | "CL" | "BR" | "H" | "D" | "T" => Some(1),
        _ => None,
    }
}
